(function(){'use strict';const STYLE_PROPS=['font-family','font-size','font-weight','font-style','text-decoration','color','background-color','vertical-align','text-transform','letter-spacing',];const FORMAT_NAME='suapformatpaint';const ICON='<svg width="24" height="24" viewBox="0 0 24 24">'+'<path d="M18 2H5a1 1 0 0 0-1 1v4a1 1 0 0 0 1 1h13a1 1 0 0 0 1-1V6h1v4H9v3a1 1 0 0 0 1 1h1v7a1 1 0 0 0 1 1h1a1 1 0 0 0 1-1v-7h1a1 1 0 0 0 1-1v-1h3V4h-3V3a1 1 0 0 0-1-1z" fill-rule="evenodd"/>'+'</svg>';tinymce.PluginManager.add('formatpainter',function(editor){let captured=null;let armed=false;let buttonApi=null;function shouldKeep(prop,value){if(!value)return false;const v=String(value).trim().toLowerCase();if(v===''||v==='normal'||v==='none'||v==='auto')return false;if(prop==='text-decoration'&&v.indexOf('none')===0)return false;if(prop==='letter-spacing'&&v==='0px')return false;if(prop==='background-color'&&(v==='transparent'||v.indexOf('rgba(0, 0, 0, 0)')===0))return false;return true;}function captureFromSelection(){const selectionNode=editor.selection.getStart();if(!selectionNode)return null;const element=selectionNode.nodeType===1?selectionNode:selectionNode.parentElement;if(!element||!editor.getBody().contains(element))return null;const computedStyle=editor.getWin().getComputedStyle(element);const styles={};STYLE_PROPS.forEach(function(prop){const value=computedStyle.getPropertyValue(prop);if(shouldKeep(prop,value)){styles[prop]=value;}});return Object.keys(styles).length?styles:null;}function setArmed(value){armed=value;if(buttonApi)buttonApi.setActive(value);}function disarm(){captured=null;setArmed(false);}function arm(){const styles=captureFromSelection();if(!styles){editor.notificationManager.open({text:'Nenhuma formatação encontrada para copiar.',type:'info',timeout:3000});return;}captured=styles;setArmed(true);}function applyCaptured(){if(!captured||editor.selection.isCollapsed())return;editor.undoManager.transact(function(){editor.formatter.register(FORMAT_NAME,{inline:'span',styles:captured});editor.formatter.apply(FORMAT_NAME);});disarm();}function onSelectionDone(){if(armed)applyCaptured();}editor.ui.registry.addIcon('format-painter',ICON);editor.ui.registry.addToggleButton('formatpainter',{icon:'format-painter',tooltip:'Pincel de formatação: copia a formatação da seleção e aplica no próximo trecho selecionado',onAction:function(){if(armed){disarm();}else{arm();}},onSetup:function(api){buttonApi=api;api.setActive(armed);editor.on('mouseup',onSelectionDone);editor.on('keyup',onSelectionDone);return function(){buttonApi=null;editor.off('mouseup',onSelectionDone);editor.off('keyup',onSelectionDone);};},});editor.on('keydown',function(e){if(armed&&e.keyCode===27){disarm();}});editor.addCommand('mceFormatPainterCancel',disarm);return{getMetadata:function(){return{name:'Format Painter (SUAP)'};},};});})();
